mapper.select:
SELECT
  (SELECT COUNT(*) FROM `user` WHERE deleted = 0)                                                       AS totalUsers,
  (SELECT COUNT(*) FROM `user` WHERE deleted = 0 AND created_at >= #{start}
     AND created_at < DATE_ADD(#{end}, INTERVAL 1 DAY))                                              AS newUsers,
  (SELECT COUNT(DISTINCT user_id) FROM user_login_log WHERE deleted = 0 AND created_at >= #{start}
     AND created_at < DATE_ADD(#{end}, INTERVAL 1 DAY))                                                 AS activeUsers,
  (SELECT COUNT(*) FROM `user` WHERE deleted = 0
     AND (last_login_at IS NULL OR last_login_at < NOW() - INTERVAL 14 DAY))                         AS silentUsers,
  (SELECT COUNT(*) FROM `user` WHERE deleted = 0 AND created_at >= #{start}
     AND created_at < DATE_ADD(#{end}, INTERVAL 1 DAY) AND last_login_at > created_at)                AS newReturnedUsers,

  (SELECT COUNT(*) FROM `user` WHERE deleted = 0 AND inviter_id IS NOT NULL AND created_at >= #{start}
     AND created_at < DATE_ADD(#{end}, INTERVAL 1 DAY))                                              AS newInvitedUsers,
  (SELECT COUNT(*) FROM `user` WHERE deleted = 0 AND inviter_id IS NULL AND created_at >= #{start}
     AND created_at < DATE_ADD(#{end}, INTERVAL 1 DAY))                                              AS newNormalUsers,

  (SELECT COUNT(DISTINCT l.user_id) FROM user_login_log l JOIN `user` u ON u.id = l.user_id AND u.deleted = 0
     WHERE l.deleted = 0 AND u.inviter_id IS NOT NULL AND l.created_at >= #{start}
     AND l.created_at < DATE_ADD(#{end}, INTERVAL 1 DAY))                                              AS activeInvitedUsers,
  (SELECT COUNT(DISTINCT l.user_id) FROM user_login_log l JOIN `user` u ON u.id = l.user_id AND u.deleted = 0
     WHERE l.deleted = 0 AND u.inviter_id IS NULL AND l.created_at >= #{start}
     AND l.created_at < DATE_ADD(#{end}, INTERVAL 1 DAY))                                              AS activeNormalUsers
